class Solution {
    public int countSubstrings(String s,String t){
        int answer=0;
        for(int first=0;first<s.length();first++)for(int second=0;second<t.length();second++){
            int mismatch=0;
            for(int offset=0;first+offset<s.length()&&second+offset<t.length();offset++){
                if(s.charAt(first+offset)!=t.charAt(second+offset))mismatch++;
                if(mismatch==1)answer++;
                else if(mismatch>1)break;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countSubstrings(s:String,t:String):Int{
        var answer=0;
        for(first in s.indices)for(second in t.indices){
            var mismatch=0;
            var offset=0;
            while(first+offset<s.length&&second+offset<t.length){
                if(s[first+offset]!=t[second+offset])mismatch++;
                if(mismatch==1)answer++ else if(mismatch>1)break;
                offset++
            }
        };
        return answer
    }
}

